import { useState, type CSSProperties } from 'react'
import { Apple, Smartphone } from 'lucide-react'
import type { PassContent } from '@/lib/walletContent'
import { useQrDataUrl } from '@/hooks/useQrDataUrl'
import { Segmented } from '@/components/ui/Tabs'
import { cn } from '@/lib/cn'
import { StampGlyph } from './StampGlyph'

type Platform = 'ios' | 'android'

function Qr() {
  // The QR is auto-generated by the system and not editable by the business (§4.3).
  const url = useQrDataUrl('BNC-PREVIEW', 160)
  return <div className="pass-qr">{url ? <img src={url} alt="Pass QR code (generated by the system)" className="size-full" /> : <div className="aspect-square" />}</div>
}

function Fields({ content }: { content: PassContent }) {
  return (
    <>
      {content.primary && (
        <>
          <p className="pass-lbl">{content.primary.label}</p>
          <p className="pass-val flex items-center gap-2">
            {content.tierBadge && <img src={content.tierBadge} alt="Tier badge" className="size-6 rounded object-cover" />}
            {content.primary.value}
          </p>
        </>
      )}
      {content.stampGrid && (
        <div className="stamps" aria-label={`${content.stampGrid.filled} of ${content.stampGrid.total} stamps`}>
          {Array.from({ length: content.stampGrid.total }, (_, i) => (
            <span key={i} className={cn('stamp', i < content.stampGrid!.filled ? 'on' : 'border-current/30 text-current/55')} style={{ animationDelay: `${i * 70}ms` }}>
              <StampGlyph icon={content.stampGrid!.icon} className="size-3.5" />
            </span>
          ))}
        </div>
      )}
      {content.progress && (
        <div className="prog">
          <i style={{ '--w': `${Math.min(100, (content.progress.value / Math.max(1, content.progress.max)) * 100)}%` } as CSSProperties} />
        </div>
      )}
      {content.secondary.length > 0 && (
        <div className="pass-cols flex-wrap gap-y-0">
          {content.secondary.map((f) => (
            <div key={f.label}>
              <p className="pass-lbl">{f.label}</p>
              <p className="pass-val sm">{f.value}</p>
            </div>
          ))}
        </div>
      )}
      {content.redeemed && <p className="mt-3 inline-block rounded-md bg-white/90 px-2 py-0.5 text-xs font-bold text-black">REDEEMED</p>}
    </>
  )
}

/**
 * Live wallet mockup: "this is how it will look on iPhone / Android" (spec §4.3), drawn with the
 * redesign phone frame and pass styles. Approximation only — real rendering is done by Apple
 * Wallet / Google Wallet.
 */
export function WalletPassPreview({ content, label = 'Live wallet preview' }: { content: PassContent; label?: string }) {
  const [platform, setPlatform] = useState<Platform>('ios')
  const logo = content.logo ? <img src={content.logo} alt="" className="pass-logo object-cover" /> : <span className="pass-logo ph">{content.title.slice(0, 1)}</span>
  const hero = content.heroImage ? <img src={content.heroImage} alt="" className="-mx-4 mt-3 h-20 w-[calc(100%+2rem)] max-w-none object-cover" /> : null

  return (
    <section aria-label={label} className="preview-col">
      <Segmented
        label="Preview platform"
        value={platform}
        onChange={setPlatform}
        items={[
          { value: 'ios', label: <><Apple className="size-[15px]" aria-hidden /> iPhone</> },
          { value: 'android', label: <><Smartphone className="size-[15px]" aria-hidden /> Android</> },
        ]}
      />

      <div className={cn('phone max-w-full', platform === 'android' && 'android')}>
        <div className="phone-screen">
          <div className="pass" style={{ '--bgp': content.background, '--fg': content.textColor } as CSSProperties} data-testid="wallet-pass">
            {platform === 'ios' ? (
              <>
                <div className="pass-top">
                  {logo}
                  <p className="pass-name truncate">{content.title}</p>
                </div>
                {hero}
                <Fields content={content} />
                <Qr />
              </>
            ) : (
              <>
                <div className="pass-top justify-start">
                  {logo}
                  <p className="truncate text-xs opacity-80">{content.title}</p>
                </div>
                <p className="pass-val mt-3 text-[22px]">{content.title}</p>
                <Fields content={content} />
                <Qr />
                {hero}
              </>
            )}
          </div>
          <p className="phone-cap">
            {content.templateName} · {platform === 'ios' ? 'Apple Wallet' : 'Google Wallet'} (approximate)
          </p>
        </div>
      </div>
    </section>
  )
}
